BEGIN;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'CUSTOMER' CHECK (role IN ('CUSTOMER','ADMIN','FINANCE')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, timezone text NOT NULL, venue text NOT NULL, description text NOT NULL DEFAULT '', instagram text NOT NULL, status text NOT NULL DEFAULT 'DRAFT', streaming_ready boolean NOT NULL DEFAULT false, CHECK (ends_at > starts_at));
CREATE TABLE ticket_classes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id), name text NOT NULL, mode text NOT NULL CHECK (mode IN ('VENUE','LIVESTREAM')), price bigint NOT NULL CHECK (price > 0), capacity integer CHECK (capacity > 0), sale_enabled boolean NOT NULL DEFAULT false, max_per_order integer NOT NULL DEFAULT 10 CHECK (max_per_order > 0), UNIQUE(event_id,name,mode), CHECK ((mode='VENUE' AND capacity IS NOT NULL) OR (mode='LIVESTREAM' AND capacity IS NULL)));
CREATE TABLE ticket_import_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket_inventory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES ticket_classes(id), batch_id uuid REFERENCES ticket_import_batches(id), file_key text NOT NULL UNIQUE, file_hash text NOT NULL UNIQUE, barcode text UNIQUE, status text NOT NULL DEFAULT 'NEEDS_REVIEW' CHECK (status IN ('AVAILABLE','RESERVED','SOLD','VOIDED','NEEDS_REVIEW')), CHECK (status IN ('VOIDED','NEEDS_REVIEW') OR barcode IS NOT NULL));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), idempotency_key uuid NOT NULL UNIQUE, status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','CONFIRMED','CANCELLED','EXPIRED')), total bigint NOT NULL CHECK (total>=0), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), class_id uuid NOT NULL REFERENCES ticket_classes(id), quantity integer NOT NULL CHECK (quantity>0), unit_price bigint NOT NULL CHECK (unit_price>0), UNIQUE(order_id,class_id));
CREATE TABLE ticket_allocations (ticket_id uuid PRIMARY KEY REFERENCES ticket_inventory(id), item_id uuid NOT NULL REFERENCES order_items(id));
CREATE TABLE stream_entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), event_id uuid NOT NULL REFERENCES events(id), order_id uuid NOT NULL REFERENCES orders(id), active boolean NOT NULL DEFAULT false, UNIQUE(user_id,event_id,order_id));
CREATE TABLE donation_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id), title text NOT NULL, description text NOT NULL DEFAULT '', target bigint CHECK(target>0));
CREATE TABLE donations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES donation_campaigns(id), user_id uuid REFERENCES users(id), donor_name text NOT NULL, anonymous boolean NOT NULL DEFAULT false, amount bigint NOT NULL CHECK(amount BETWEEN 10000 AND 100000000), status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','VERIFIED','REJECTED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, resource_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE site_settings (key text PRIMARY KEY, value jsonb NOT NULL);
INSERT INTO events(title,starts_at,ends_at,timezone,venue,instagram) VALUES ('Symphony of Faith','2027-02-07T19:00:00+07:00','2027-02-07T22:00:00+07:00','Asia/Jakarta','Tiara Convention Hall, Medan','https://www.instagram.com/symphonyoffaithconcert?cnvx=MWN3ZnViYmMwZWtuYw==');
INSERT INTO ticket_classes(event_id,name,mode,price,capacity) SELECT e.id,p.name,'VENUE',p.price,p.capacity FROM events e CROSS JOIN (VALUES ('Platinum',2000000,70),('Gold',1000000,170),('Silver',500000,270),('Bronze',250000,570),('Reguler',100000,770)) AS p(name,price,capacity);
INSERT INTO ticket_classes(event_id,name,mode,price) SELECT e.id,p.name,'LIVESTREAM',p.price FROM events e CROSS JOIN (VALUES ('Platinum',1000000),('Gold',500000),('Silver',250000),('Bronze',100000),('Reguler',50000)) AS p(name,price);
COMMIT;
